import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import ItemList from 'flarum/common/utils/ItemList';
export default class SettingsPage extends ExtensionPage {
  content() {
    return m("div", {
      className: "FoFDefaultPreferencesSettingsPage"
    }, m("div", {
      className: "container"
    }, m("div", {
      className: "Form-group"
    }, this.defaultSettingsItems().toArray(), this.submitButton())));
  }
  defaultSettingsItems() {
    const items = new ItemList();
    const prefix = 'fof-default-user-preferences.';
    app.forum.attribute('fof-default-user-preferences').forEach(pref => {
      const key = pref.key;
      const type = pref.type;
      const placeholder = pref.value;
      items.add(key, this.buildSettingComponent({
        label: app.translator.trans(`fof-default-user-preferences.admin.settings.${key}`),
        help: app.translator.trans(`fof-default-user-preferences.admin.settings.${key}-help`),
        setting: prefix + key,
        type,
        placeholder
      }));
    });
    return items;
  }
}
flarum.reg.add('framio-community', 'default-user-preferences/admin/components/SettingsPage', SettingsPage);